 ToolTip BrowserHint(string text){return new ToolTip{Content=text,Resources=Resources,Style=(Style)Resources["BrowserToolTip"]};}
 TextBlock Text(string text,double size,string resource){var label=new TextBlock{Text=text,FontSize=size,VerticalAlignment=VerticalAlignment.Center};label.SetResourceReference(TextBlock.ForegroundProperty,resource);return label;}
 Button TextButton(string text,Action action,string hint){var b=new Button{Content=text,ToolTip=BrowserHint(hint),Style=(Style)Resources["BrowserChromeButton"],Height=38,Padding=new Thickness(13,0,13,0),Margin=new Thickness(2),FontSize=13,FontWeight=FontWeights.SemiBold,Cursor=Cursors.Hand};b.SetResourceReference(Control.ForegroundProperty,"Text");System.Windows.Automation.AutomationProperties.SetName(b,hint);b.Click+=(s,e)=>action();return b;}
 Button IconButton(string icon,Action action,string hint){var b=TextButton("",action,hint);b.Content=ChromeIcon(icon);b.Width=34;b.Height=36;b.Padding=new Thickness(0);return b;}
 Path ChromeIcon(string name){
  string shape;
  switch(name){
   case "back":shape="M19,12 L5,12 M11,5 L4,12 11,19";break;
   case "forward":shape="M5,12 L19,12 M13,5 L20,12 13,19";break;
   case "reload":shape="M20,8 A8,8 0 1 0 20,16 M20,3 L20,9 14,9";break;
   case "close":shape="M6,6 L18,18 M18,6 L6,18";break;
   case "minimize":shape="M5,12 L19,12";break;
   case "maximize":shape="M5,5 L19,5 19,19 5,19 Z";break;
   case "add":shape="M12,4 L12,20 M4,12 L20,12";break;
   case "menu":shape="M12,4 A1,1 0 1 1 12,6 A1,1 0 1 1 12,4 M12,11 A1,1 0 1 1 12,13 A1,1 0 1 1 12,11 M12,18 A1,1 0 1 1 12,20 A1,1 0 1 1 12,18";break;
   case "star":shape="M12,2 L15,8.5 22,9.5 17,14.5 18.2,22 12,18.5 5.8,22 7,14.5 2,9.5 9,8.5 Z";break;
   case "pin":shape="M8,3 L16,3 M9,3 L9,9 C9,11 6,11 6,14 L18,14 C18,11 15,11 15,9 L15,3 M12,14 L12,22";break;
   case "cinema":shape="M4,4 L20,4 20,20 4,20 Z M4,8 L20,8";break;
   case "sound":shape="M3,10 L7,10 12,5 12,19 7,14 3,14 Z M16,8 Q21,12 16,16 M19,5 Q26,12 19,19";break;
   case "silent":shape="M3,10 L7,10 12,5 12,19 7,14 3,14 Z M17,9 L23,15 M23,9 L17,15";break;
   case "edit":shape="M4,16 L16,4 20,8 8,20 3,21 Z M13,7 L17,11";break;
   default:shape="M22,12 A10,10 0 1 1 2,12 A10,10 0 1 1 22,12 M2,12 L22,12 M12,2 C5,6 5,18 12,22 C19,18 19,6 12,2";break;
  }
  var p=new Path{Data=Geometry.Parse(shape),Width=19,Height=19,Stretch=Stretch.Uniform,StrokeThickness=1.7,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,StrokeLineJoin=PenLineJoin.Round,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,IsHitTestVisible=false};p.SetResourceReference(Shape.StrokeProperty,"Text");return p;
 }
 bool LibraryAction(Action action){try{action();UpdateBookmark();if(libraryLayer!=null&&editingBookmark==null)RenderLibrary();return true;}catch(Exception error){if(!disposed)status.Text="Не удалось сохранить: "+error.Message;return false;}}
 void UpdateBookmark(){if(current==null)return;bool saved=library.IsBookmarked(current.Url);var icon=ChromeIcon("star");if(saved){icon.SetResourceReference(Shape.FillProperty,"Accent");icon.SetResourceReference(Shape.StrokeProperty,"Accent");}bookmarkButton.Content=icon;bookmarkButton.IsEnabled=current.Ready&&current.Succeeded;bookmarkButton.ToolTip=BrowserHint(saved?"Удалить страницу из закладок (Ctrl+D)":"Добавить страницу в закладки (Ctrl+D)");System.Windows.Automation.AutomationProperties.SetName(bookmarkButton,saved?"Удалить страницу из закладок":"Добавить страницу в закладки");}
 void ToggleBookmark(){if(current==null||!current.Ready||!current.Succeeded){status.Text="Дождись загрузки страницы, чтобы сохранить её.";return;}LibraryAction(()=>library.ToggleBookmark(current.Url,current.Title));}
 void OpenMenu(){var menu=BuildBrowserMenu();menuButton.ContextMenu=menu;menu.IsOpen=true;}
 ContextMenu BuildBrowserMenu(){
  var menu=new ContextMenu{Resources=Resources,Style=(Style)Resources["BrowserContextMenu"],PlacementTarget=menuButton,Placement=System.Windows.Controls.Primitives.PlacementMode.Custom,MinWidth=270,MaxHeight=Math.Max(120,SystemParameters.WorkArea.Height-28),UseLayoutRounding=true,SnapsToDevicePixels=true};
  menu.CustomPopupPlacementCallback=(popup,target,offset)=>new[]{new System.Windows.Controls.Primitives.CustomPopupPlacement(new Point(target.Width-popup.Width,target.Height+5),System.Windows.Controls.Primitives.PopupPrimaryAxis.Vertical),new System.Windows.Controls.Primitives.CustomPopupPlacement(new Point(target.Width-popup.Width,-popup.Height-5),System.Windows.Controls.Primitives.PopupPrimaryAxis.Vertical)};menu.SetResourceReference(Control.BackgroundProperty,"DockBg");menu.SetResourceReference(Control.ForegroundProperty,"Text");menu.SetResourceReference(Control.BorderBrushProperty,"Line");
  Action<string,string,Action> add=(label,keys,action)=>{var item=new MenuItem{Header=label,InputGestureText=keys,Padding=new Thickness(9,7,9,7),Style=(Style)Resources["BrowserMenuItem"]};item.Click+=(s,e)=>action();menu.Items.Add(item);};
  add("Новая вкладка","Ctrl+T",()=>AddPage(null));add("Закрыть вкладку","Ctrl+W",()=>ClosePage(current));menu.Items.Add(new Separator{Style=(Style)Resources["BrowserMenuSeparator"]});add("История","Ctrl+H",()=>ShowLibrary(true));add("Закладки","Ctrl+Shift+O",()=>ShowLibrary(false));add("Сохранить страницу","Ctrl+D",ToggleBookmark);menu.Items.Add(new Separator{Style=(Style)Resources["BrowserMenuSeparator"]});add("Стартовая страница","",()=>Go(HomeUrl(HomeProvider)));add("YouTube","",()=>Go("https://www.youtube.com/"));add("Fletcher Wiki","",()=>Go("https://fletcher-wiki.com/"));menu.Items.Add(new Separator{Style=(Style)Resources["BrowserMenuSeparator"]});add(Topmost?"Открепить окно":"Поверх всех окон","",()=>{Topmost=!Topmost;UpdatePin();RefreshPage();});add(viewMode?"Вернуть панели":"Режим просмотра","F11",()=>SetViewMode(!viewMode));add(muted||Volume==0?"Включить звук":"Выключить звук","",ToggleMute);return menu;
 }
 void ShowLibrary(bool history){
  SetViewMode(false);CloseLibrary();showingHistory=history;editingBookmark=null;
  libraryLayer=new Grid();var shade=new Border{Background=Brushes.Black,Opacity=.4};shade.MouseLeftButtonDown+=(s,e)=>{CloseLibrary();e.Handled=true;};libraryLayer.Children.Add(shade);
  libraryPanel=new Border{Width=400,MaxWidth=Math.Max(1,pageHost.ActualWidth-16),HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(8),CornerRadius=new CornerRadius(16),BorderThickness=new Thickness(1),Padding=new Thickness(16)};libraryPanel.SetResourceReference(Border.BackgroundProperty,"DockBg");libraryPanel.SetResourceReference(Border.BorderBrushProperty,"Line");libraryLayer.Children.Add(libraryPanel);
  var body=new Grid();for(int i=0;i<5;i++)body.RowDefinitions.Add(new RowDefinition{Height=i==3?new GridLength(1,GridUnitType.Star):GridLength.Auto});libraryPanel.Child=body;
  var header=new DockPanel();var close=IconButton("close",CloseLibrary,"Закрыть историю и закладки (Esc)");DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);var title=Text(history?"История":"Закладки",22,"Text");title.FontWeight=FontWeights.SemiBold;header.Children.Add(title);body.Children.Add(header);
  var modes=new WrapPanel{Margin=new Thickness(0,8,0,8)};var h=TextButton("История",()=>ShowLibrary(true),"История посещённых страниц");var b=TextButton("Закладки",()=>ShowLibrary(false),"Сохранённые страницы");(history?h:b).SetResourceReference(Control.BackgroundProperty,"SelectedTab");modes.Children.Add(h);modes.Children.Add(b);Grid.SetRow(modes,1);body.Children.Add(modes);
  var filters=new StackPanel();librarySearch=new TextBox{Tag=history?"Найти в истории":"Найти закладку",Padding=new Thickness(10,8,10,8),Margin=new Thickness(0,0,0,10),FontSize=13};librarySearch.SetResourceReference(Control.BackgroundProperty,"Field");librarySearch.SetResourceReference(Control.ForegroundProperty,"Text");librarySearch.SetResourceReference(Control.BorderBrushProperty,"Line");System.Windows.Automation.AutomationProperties.SetName(librarySearch,history?"Поиск по истории":"Поиск по закладкам");filters.Children.Add(librarySearch);
  if(history){var recording=new CheckBox{Content="Сохранять историю",IsChecked=library.Data.RecordHistory,Margin=new Thickness(2,0,0,12),Style=(Style)Resources["BrowserHistoryCheck"]};recording.SetResourceReference(Control.ForegroundProperty,"Text");recording.Click+=async(s,e)=>{bool saved=LibraryAction(()=>library.SetRecording(recording.IsChecked==true));recording.IsChecked=library.Data.RecordHistory;if(saved&&!library.Data.RecordHistory)await ClearEngineHistory();};filters.Children.Add(recording);}Grid.SetRow(filters,2);body.Children.Add(filters);
  libraryRows=new StackPanel();var scroll=new ScrollViewer{Content=libraryRows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,3);body.Children.Add(scroll);
  if(history){var clear=TextButton("Очистить историю",async()=>{if(MessageBox.Show(this,"Удалить всю историю посещений? Закладки останутся.","Очистить историю",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes&&LibraryAction(library.ClearHistory))await ClearEngineHistory();},"Удалить всю историю посещений");clear.Margin=new Thickness(0,10,0,0);Grid.SetRow(clear,4);body.Children.Add(clear);}
  librarySearch.TextChanged+=(s,e)=>RenderLibrary();pageHost.Children.Add(libraryLayer);RenderLibrary();libraryPanel.RenderTransform=new TranslateTransform();((TranslateTransform)libraryPanel.RenderTransform).BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(18,0,TimeSpan.FromMilliseconds(160)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});libraryPanel.BeginAnimation(OpacityProperty,new DoubleAnimation(0,1,TimeSpan.FromMilliseconds(160)));librarySearch.Focus();
 }
 void CloseLibrary(){if(libraryLayer==null)return;pageHost.Children.Remove(libraryLayer);libraryLayer=null;libraryPanel=null;libraryRows=null;librarySearch=null;editingBookmark=null;}
 void RenderLibrary(){
  if(libraryRows==null)return;libraryRows.Children.Clear();var entries=library.Find(showingHistory,librarySearch.Text).ToList();
  if(entries.Count==0){var empty=Text(librarySearch.Text.Length>0?"Ничего не найдено":showingHistory?"Посещённые страницы появятся здесь.":"Нажми звёздочку в адресной строке, чтобы сохранить страницу.",13,"Muted");empty.TextWrapping=TextWrapping.Wrap;empty.Margin=new Thickness(3,16,3,16);libraryRows.Children.Add(empty);return;}
  foreach(var entry in entries){var item=entry;var border=new Border{CornerRadius=new CornerRadius(11),Margin=new Thickness(0,0,0,7),Padding=new Thickness(6),BorderThickness=new Thickness(1)};border.SetResourceReference(Border.BackgroundProperty,"NavBg");border.SetResourceReference(Border.BorderBrushProperty,"Line");libraryRows.Children.Add(border);
   if(editingBookmark==item.Id&&!showingHistory){var edit=new StackPanel();var field=new TextBox{Text=item.Title,MaxLength=300,FontSize=13,Padding=new Thickness(8),Margin=new Thickness(0,0,0,5)};field.SetResourceReference(Control.BackgroundProperty,"Field");field.SetResourceReference(Control.ForegroundProperty,"Text");field.SetResourceReference(Control.BorderBrushProperty,"Line");edit.Children.Add(field);Action save=()=>{editingBookmark=null;if(!LibraryAction(()=>library.RenameBookmark(item.Id,field.Text)))editingBookmark=item.Id;};field.KeyDown+=(s,e)=>{if(e.Key==Key.Enter){save();e.Handled=true;}};var commands=new WrapPanel();commands.Children.Add(TextButton("Сохранить",save,"Сохранить название закладки"));commands.Children.Add(TextButton("Отмена",()=>{editingBookmark=null;RenderLibrary();},"Отменить переименование"));edit.Children.Add(commands);border.Child=edit;field.Focus();field.SelectAll();continue;}
   var row=new DockPanel{LastChildFill=true};border.Child=row;var commandsRow=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Top};DockPanel.SetDock(commandsRow,Dock.Right);row.Children.Add(commandsRow);
   if(!showingHistory)commandsRow.Children.Add(IconButton("edit",()=>{editingBookmark=item.Id;RenderLibrary();},"Переименовать закладку"));commandsRow.Children.Add(IconButton("close",()=>LibraryAction(()=>library.Remove(item.Id,showingHistory)),showingHistory?"Удалить запись истории":"Удалить закладку"));
   var open=TextButton("",()=>Go(item.Url),"Открыть "+item.Title);open.Height=Double.NaN;open.MinHeight=56;open.Padding=new Thickness(4);open.HorizontalContentAlignment=HorizontalAlignment.Stretch;open.ToolTip=BrowserHint(item.Url);var labels=new StackPanel();var title=Text(item.Title,13,"Text");title.TextTrimming=TextTrimming.CharacterEllipsis;labels.Children.Add(title);var url=Text(item.Url,10,"Muted");url.TextTrimming=TextTrimming.CharacterEllipsis;url.Margin=new Thickness(0,4,0,0);labels.Children.Add(url);
   if(showingHistory){DateTime time;if(DateTime.TryParse(item.VisitedUtc,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out time)){var date=Text(time.ToLocalTime().ToString("dd.MM · HH:mm"),10,"Muted");date.Margin=new Thickness(0,4,0,0);labels.Children.Add(date);}}open.Content=labels;row.Children.Add(open);
  }
 }
